let app_version = "1.4.4";
let secretKey = "Gnzg4OfHHp103jx8ebG82gA8VPJZnLTk";
let app_signature_md5 = "02ebc876b59abf1294791faf89cf04d7";
let config = {
  BASEURL: "https://app.cddaoyue.cn",
  app_signature_md5: app_signature_md5,
  app_version: app_version,
  channel: "Common",
  UserAgent: `Android`,
  login_token: "",
  account: ""
}

//获取源变量
function getData() {
  const {
    source
  } = this;
  try {
    return JSON.parse(source.getVariable());
  } catch (err) {
    return {};
  }
}

//保存源变量 setData(data)
function setData(obj) {
  const {
    source
  } = this;
  if (typeof obj == "object") {
    source.setVariable(JSON.stringify(obj, null, 1));
  }
}

function URL(path, searchParams) {
  const {
    source,
    java
  } = this;
  let data = this.getData();
  if (!data["login_token"] || !data["account"]) {
    // java.log("登录中...")
    java.toast("登录中...");
    // this.login();
    eval(String(source.loginUrl));
    login.call(this);
  }
  let url = this._URL(path, searchParams);
  return url
}

function _URL(path, searchParams, isLogin) {
  const {
    java
  } = this;
  let params = ["app_signature_md5", "app_version", "channel"];
  if (typeof searchParams !== 'object') searchParams = {};
  if (!isLogin) {
    params = ["app_signature_md5", "app_version", "channel", "account", "login_token"];
    let data = this.getData();
    config.login_token = data["login_token"];
    config.account = data["account"];
  }

  for (let paramkey of params) {
    if (config[paramkey]) searchParams[paramkey] = config[paramkey];
  }
  let body = `secret_content=${this.encrypt(searchParams)}`
  return `${config.BASEURL}${path},${JSON.stringify({ method: "POST", body: body, headers: { "User-Agent": config.UserAgent } })}`
}

function encrypt(decrypted) {
  const {
    java
  } = this;
  let aesKey = java.hexDecodeToByteArray(java.digestHex(secretKey, "SHA-256"));
  let iv = java.hexDecodeToByteArray("0".repeat(32));
  let aesDecipher = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", aesKey, iv);
  decrypted = JSON.stringify(decrypted);
  let encrypted = aesDecipher.encryptBase64(decrypted);
  return encrypted
}

function decrypt(encrypted, key) {
  const {
    java
  } = this;
  let aesKey = java.hexDecodeToByteArray(java.digestHex(key || secretKey, "SHA-256"));
  let iv = java.hexDecodeToByteArray("0".repeat(32));
  let aesDecipher = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", aesKey, iv);
  let decrypted = aesDecipher.decryptStr(encrypted);
  try {
    decrypted = JSON.parse(decrypted);
    if (decrypted.code != "100000") {
      java.toast(decrypted.tip);
    }
  } catch (error) { }
  return decrypted
}
/**
 * 获取一个游客账户
 */
function auto_reg() {
  const {
    java
  } = this;
  let url = this._URL(`/signup/auto_reg`, {
    uuid: "android" + java.randomUUID()
  }, true)
  return url;
}
/**
 * 使用手机号以及密码进行登录
 */
function Login(searchParams) {
  let url = this._URL(`/signup/login`, searchParams, true);
  return url;
}

/**
 * 搜索关键词
 * @param word 搜索词
 * @param page 页数
 * @param order 类型
 * 人气排序 week_click
 * 更新时间 uptime
 * 总推荐 total_recommend
 * 总收藏 total_favor
 * 总月票 total_yp
 * 总点击 total_click
 * 总段评 total_tsukkomi
 * @param filter_word 字数
 * 15万以下 1
 * 15-30万 2
 * 30-50万 3
 * 50-100万 4
 * 100-200万 5
 * 200万以上 6
 * @param is_paid 付费
 * 免费 0
 * 付费 1
 * @param up_status 连载
 * 连载 0
 * 完本 1
 * @param filter_uptime 更新
 * 3天内 1
 * 7天内 2
 * 半个月内 3
 * 一个月内 4
 */
function search(word, page) {
  return this.URL(`/bookcity/get_filter_search_book_list`, {
    count: 15,
    page: page - 1,
    category_index: 0,
    key: word,
    order: "week_click"
  })
}

/**
 * 搜索tag
 * @param tag tag
 * @param page 页数
 */
function tag(tag, page) {
  return this.URL(`/bookcity/get_filter_search_book_list`, {
    count: 15,
    page: page - 1,
    tag: tag,
    order: "week_click"
  })
}

/**
 * 获取排行榜
 * @param order 排序
 * @param time_type 时间类型 "week" | "month" | "total"
 * @param page 页数
 * @param category_index 分类ID
 */
function rank(order, time_type, page, category_index) {
  const u = this.URL(`/bookcity/get_rank_book_list`, {
    time_type: time_type,
    page: page - 1,
    count: 12,
    category_index: category_index,
    order: order
  })
}

/**
 * 购买章节
 * @param chapid 章节ID
 */
function buy(chapid) {
  const {
    java
  } = this;
  let url = this.URL(`/chapter/buy`, {
    chapter_id: chapid
  })
  let result = java.ajax(url);
  result = this.decrypt(result);
  // java.log(JSON.stringify(result))
  return result
}

